_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv_transpose3d_kernel")

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0,
                 output_padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.conv_transpose3d = nn.ConvTranspose3d(in_channels, out_channels, (kernel_size, kernel_size, kernel_size),
                                                     stride=stride, padding=padding, output_padding=output_padding,
                                                     dilation=dilation, groups=groups, bias=bias)
        assert kernel_size == 3
        assert stride == 1
        assert padding == 0
        assert output_padding == 0
        assert dilation == 1
        assert groups == 1
        assert bias is False
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda
        x = x.contiguous()
        weight = self.conv_transpose3d.weight.contiguous()

        B, IC, Din, Hin, Win = x.shape
        OC = weight.shape[1]
        K = self.kernel_size

        Dout = Din + K - 1
        Hout = Hin + K - 1
        Wout = Win + K - 1

        out = torch.empty((B, OC, Dout, Hout, Wout), device=x.device, dtype=x.dtype)

        block_x = 128
        grid_x = (Wout + block_x - 1) // block_x
        grid_y = Hout
        grid_z = B * Dout

        module = _get_ptx_module()
        module.launch(
            "conv_transpose3d_kernel",
            grid=(grid_x, grid_y, grid_z),
            block=(block_x, 4, 1),
            arguments=[
                x, weight, out,
                i32(B), i32(IC), i32(OC),
                i32(Din), i32(Hin), i32(Win),
                i32(Dout), i32(Hout), i32(Wout),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

